fn qnorm_against_r() {
    for row in fixture("qnorm.tsv") {
        let (p, lower, logp, mu, sigma) = (f(&row[0]), row[1] == "1", row[2] == "1", f(&row[3]), f(&row[4]));
        assert_same(qnorm(p, mu, sigma, lower, logp), f(&row[5]),
                    &format!("qnorm({p:e}, {mu}, {sigma}, lower = {lower}, log = {logp})"));
    }
}

